    10	import java.util.LinkedHashMap;
    11	import java.util.List;
    12	import java.util.Map;
    13	
    14	/**
    15	 * Marketing's monthly "top earners" list, from what the earn run sent to the vendor this
    16	 * month (our own earn ledger), not from the vendor balance.
    17	 */
    18	// TODO: the member app already shows the vendor balance -- do we still need our own count here?
    19	public class TopEarnersReport {
    20	    public record Row(String memberNo, String name, long points) {}
    21	
    22	    private final MemberDirectory members;
    23	    private final EarnLedger ledger;
    24	
    25	    public TopEarnersReport(MemberDirectory members, EarnLedger ledger) {
    26	        this.members = members;
    27	        this.ledger = ledger;
    28	    }
    29	
    30	    public List<Row> top(YearMonth month, int n) {
    31	        Map<String, Long> sums = new LinkedHashMap<>();
    32	        for (EarnEntry e : ledger.all()) {
    33	            if (YearMonth.from(e.day()).equals(month)) sums.merge(e.memberNo(), e.points(), Long::sum);
    34	        }
    35	        List<Row> rows = new ArrayList<>();
    36	        for (Map.Entry<String, Long> s : sums.entrySet()) {
    37	            String name = members.find(s.getKey()).map(Member::name).orElse("?");
    38	            rows.add(new Row(s.getKey(), name, s.getValue()));
    39	        }
    40	        rows.sort(Comparator.comparingLong(Row::points).reversed().thenComparing(Row::memberNo));
    41	        return rows.size() > n ? rows.subList(0, n) : rows;
    42	    }
    43	}

