package service;

import domain.Member;
import infra.PtsctlClient;

import java.util.regex.Pattern;

/**
 * Customer-care compensation: points credited by hand-off from the support desk, one per ticket.
 * The vendor reference is "A-" + ticket number, so the vendor refuses a second credit for the same
 * ticket. Compensation is never recorded in our earn ledger, so it stays out of the monthly
 * top-earners list. The member's balance and entry count still include it (vendor values).
 * The "E-" prefix is reserved for payment earns; do not reuse it here.
 */
public class CompensationService {
    static final String REF_PREFIX = "A-";
    private static final Pattern TICKET = Pattern.compile("[A-Za-z0-9-]{1,30}");

    private final MemberDirectory members;
    private final PtsctlClient pts;

    public CompensationService(MemberDirectory members, PtsctlClient pts) {
        this.members = members;
        this.pts = pts;
    }

    /** Credits compensation points and returns the vendor entry number. Refuses before any credit. */
    public String compensate(String memberNo, long points, String ticketNo) {
        if (points <= 0) throw new IllegalArgumentException("points must be positive: " + points);
        if (ticketNo == null || !TICKET.matcher(ticketNo).matches()) {
            throw new IllegalArgumentException("invalid ticket number: " + ticketNo);
        }
        Member m = members.find(memberNo).orElseThrow(() -> new IllegalArgumentException("unknown member " + memberNo));
        return pts.earn(m.memberNo(), points, REF_PREFIX + ticketNo);
    }
}

